/* cppi::cd13b75926e7a6e1273314f3403765c4f3509a72c10b3962e067925a6706f7ff */
select count(*) from asset.asset_security_identifiers shm  where cast(shm.business_date as varchar)  = '2025-06-05'

LIMIT 200

/* cppi::3363ddb89198e33c241ed9964d5a953644e1264c3502a328ce193adf3db6453b */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-05' and business_date <= date '2025-06-05' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0' and security_id is not null

/* cppi::3e13367c7c3c01611c310b80077d89f400a0557e60a6c814f8b1ee2fdb6edb46 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-05-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-12-31'
    ) a
where arrival_time = max_publish

/* cppi::f2da25e990838955f7f23f7a10767a778f7c3d852d9297676a126249ad23325c */
select id_isin as identifier, cppib_sec_id as ID_CPPIBSEC, ticker_exch_cd as ticker from asset.qsrp_security_equity_latest
     where id_isin is not null and cppib_sec_id is not null

/* cppi::5675f782e8e82d2924bf922fd840515171a2ba09acf1b700679cecad2c2ad419 */
select cppib_sector_classification_name_1, * from asset_uat.enterprise_security  
where business_date = date '2025-05-23' and enterprise_security_id like '%-sec-prty-ltID'

